22	export function loadProfiles(dir: string): Map<string, DistillProfile> {
23	  const profiles = new Map<string, DistillProfile>();
24	  for (const file of readdirSync(dir).filter((f) => f.endsWith('.yaml'))) {
25	    const profile = loadYamlFile(path.join(dir, file), DistillProfileSchema);
26	    profiles.set(profile.name, profile);
27	  }
