86	async function fileSkeletonDistill(
87	  raw: string,
88	  profile: DistillProfile,
89	  context: DistillContext,
90	): Promise<string> {
91	  const lang: SkeletonLanguage =
92	    (context.filePath !== undefined ? languageForPath(context.filePath) : undefined) ?? 'ts';
93	  const allowed = (ruleConfig(profile, 'skeleton')['languages'] as string[] | undefined) ?? ['ts'];
94	  if (!allowed.includes(lang)) return '';
95	  const header = context.filePath === undefined ? [] : [`skeleton of ${context.filePath}`];
96	  const skeleton = await fileSkeleton(raw, lang);
97	  const withZoom = skeleton.replace(
98	    /^\[(\d+ import lines omitted)\]/,
99	    (_m, inner: string) => `[${inner}, ${zoomRef(context)}]`,
100	  );
101	  return [
102	    ...header,
103	    `[bodies elided, ${zoomRef(context)}]`,
104	    withZoom,
105	  ].join('\n');
106	}
