185	  const g = profile.gates;
186	  return {
187	    entity:
188	      g.relevantLinePattern === undefined
189	        ? undefined
190	        : {
191	            relevantLinePattern: g.relevantLinePattern,
192	            minRatio: g.entityPreservationMinRatio,
193	            limit: g.relevantLineLimit,
