226	export async function distillArtifact(
227	  store: Store,
228	  audit: AuditWriter,
229	  request: DistillRequest,
230	): Promise<DistillOutcome> {
231	  const artifactId = `a${randomBytes(3).toString('hex')}`;
232	  const distilled = await runProfile(request.profile, request.raw, {
233	    ...request.context,
234	    artifactId,
235	  });
236	  const gateConfig = profileGateConfig(request.profile);
237	  const gateReport = runGates(request.raw, distilled, gateConfig);
238	  const served = gateReport.passed ? 'distilled' : 'raw';
239	  const stored = storeRedactedArtifact(store, audit, {
240	    id: artifactId,
241	    sessionId: request.sessionId,
242	    artifactClass: request.profile.name,
243	    tool: request.tool,
244	    createdAt: new Date().toISOString(),
245	    raw: request.raw,
246	    distilled: gateReport.passed ? distilled : undefined,
247	    profile: request.profile.name,
248	    gatesPassed: gateReport.passed,
249	    meta: { gates: gateReport.results },
250	  });
251	  const bytesIn = Buffer.byteLength(request.raw, 'utf8');
252	  const bytesOut = Buffer.byteLength(gateReport.passed ? distilled : request.raw, 'utf8');
253	  const event: AuditEvent = {
254	    id: `${served}-${artifactId}`,
255	    timestamp: new Date().toISOString(),
256	    sessionId: request.sessionId,
257	    module: 'sidecar.distill',
258	    action: served === 'distilled' ? 'distill' : 'serve-raw',
259	    reason:
260	      served === 'distilled'
261	        ? `profile ${request.profile.name} served ${bytesOut}B for ${bytesIn}B raw`
262	        : `profile ${request.profile.name} gate failure, raw served: ${gateReport.results
263	            .filter((r) => !r.passed)
264	            .map((r) => `${r.gate} (${r.detail})`)
265	            .join('; ')}`,
266	    inputRef: artifactId,
267	    bytesIn,
268	    bytesOut,
269	    // Founder review 2026-07-19: the exact gate configuration rides along with
270	    // every event so any gate softening is visible in the trail.
271	    details: { profile: request.profile.name, gates: gateReport.results, gateConfig },
272	  };
273	  audit.write(event);
274	  store.insertAuditEvent(event);
275	  const handle = makeHandle(artifactId, request.raw, gateReport.passed ? distilled : request.raw);
276	  return {
277	    served,
278	    text: served === 'distilled' ? (stored.distilled ?? distilled) : stored.raw,
279	    handle,
280	    artifactId,
281	    gateReport,
282	  };
283	}
284	
285	export interface ZoomResult {
286	  found: boolean;
287	  text: string;
288	}
289	
290	export function zoom(store: Store, audit: AuditWriter, id: string, query?: string): ZoomResult {
291	  const artifact = store.getArtifact(id);
292	  if (artifact === undefined) return { found: false, text: `no artifact ${id} in the store` };
293	  let text = artifact.raw;
294	  if (query !== undefined && query !== '') {
295	    const lines = artifact.raw.split(/\r?\n/);
296	    const matcher = new RegExp(query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i');
297	    const keep = new Set<number>();
298	    lines.forEach((line, i) => {
299	      if (matcher.test(line)) {
300	        for (let j = Math.max(0, i - 2); j <= Math.min(lines.length - 1, i + 2); j += 1) keep.add(j);
301	      }
302	    });
303	    const slice = [...keep].sort((a, b) => a - b).slice(0, 200);
304	    text =
305	      slice.length === 0
306	        ? `no lines matching "${query}" in artifact ${id}; zoom without a query for the full raw artifact`
307	        : slice.map((i) => lines[i]).join('\n');
308	  }
309	  const event: AuditEvent = {
310	    id: `zoom-${id}-${randomBytes(2).toString('hex')}`,
311	    timestamp: new Date().toISOString(),
312	    sessionId: artifact.sessionId,
313	    module: 'sidecar.zoom',
314	    action: 'zoom',
315	    reason: query === undefined || query === '' ? `raw artifact ${id} served` : `query slice of ${id} for "${query}"`,
316	    inputRef: id,
317	    details: { query: query ?? null },
318	  };
319	  audit.write(event);
320	  store.insertAuditEvent(event);
321	  return { found: true, text };
322	}
