122	      return;
123	    }
124	    if (req.method === 'POST' && (url.pathname === '/distill' || url.pathname === '/zoom')) {
125	      if (engines === undefined) {
126	        respond(503, { ok: false, error: 'daemon started without a profiles directory' });
127	        return;
128	      }
129	      void readBody(req)
130	        .then(async (payload) => {
131	          const p = payload as Record<string, unknown>;
132	          if (url.pathname === '/zoom') {
133	            respond(200, zoom(engines.store, engines.audit, String(p['id']), p['query'] as string | undefined));
