203	export async function startDaemon(options: DaemonOptions): Promise<DaemonHandle> {
204	  const log = createLogger(path.join(options.dcpDir, 'sidecar.log.jsonl'));
205	  let engines: Engines | undefined;
206	  if (options.profilesDir !== undefined) {
207	    engines = {
208	      store: openStore(path.join(options.dcpDir, 'state.db')),
209	      audit: new AuditWriter(path.join(options.dcpDir, 'audit.jsonl')),
210	      profiles: loadProfiles(options.profilesDir),
211	    };
212	  }
213	  const repoRoot = path.dirname(path.resolve(options.dcpDir));
214	  const onFileChange = async (filePath: string): Promise<string[]> => {
215	    try {
216	      const rel = path.isAbsolute(filePath) ? path.relative(repoRoot, filePath) : filePath;
217	      return await refreshFiles(repoRoot, [rel]);
218	    } catch {
219	      return [];
220	    }
221	  };
222	  const onNotify = async (event: { kind: string; tool?: string; path?: string }): Promise<void> => {
223	    try {
224	      await updateRollingState(options.dcpDir, event);
225	    } catch {
226	      // State maintenance must never fail a notify.
227	    }
228	  };
229	  const listener = handler(log, engines, onFileChange, onNotify);
230	  const httpServer = http.createServer(listener);
231	  await new Promise<void>((resolve, reject) => {
232	    httpServer.once('error', reject);
233	    httpServer.listen(options.port, '127.0.0.1', resolve);
234	  });
235	  const address = httpServer.address();
236	  const port = typeof address === 'object' && address !== null ? address.port : options.port;
237	
238	  let pipeServer: http.Server | undefined;
239	  let pipePath: string | undefined;
240	  if (options.pipeName !== undefined && process.platform === 'win32') {
241	    pipePath = `\\\\.\\pipe\\${options.pipeName}`;
242	    pipeServer = http.createServer(listener);
243	    await new Promise<void>((resolve, reject) => {
244	      pipeServer?.once('error', reject);
245	      pipeServer?.listen(pipePath, resolve);
246	    });
247	  }
248	
249	  const pidfile = path.join(options.dcpDir, 'sidecar.pid.json');
250	  writeFileSync(pidfile, JSON.stringify({ pid: process.pid, port, pipePath }) + '\n', 'utf8');
251	  log.info('daemon started', { port, pipePath, pid: process.pid });
252	
253	  const close = async (): Promise<void> => {
254	    await Promise.all(
255	      [httpServer, pipeServer]
256	        .filter((s): s is http.Server => s !== undefined)
257	        .map(
258	          (s) =>
259	            new Promise<void>((resolve) => {
260	              s.close(() => resolve());
261	              s.closeAllConnections();
262	            }),
263	        ),
264	    );
265	    engines?.store.close();
266	    if (existsSync(pidfile)) rmSync(pidfile);
267	    log.info('daemon stopped', { port });
268	  };
269	  process.once('redutok:shutdown' as never, () => {
270	    void close();
271	  });
272	  return { port, pipePath, pidfile, close };
273	}
